SELECT o.id, o.order_no AS orderNo, o.customer_order_no AS customerOrderNo, o.customer_id AS customerId, c.name AS customerName, o.order_date AS orderDate, o.total_amount AS totalAmount, o.status AS status, o.expected_delivery AS expectedDelivery, o.due_date AS dueDate, o.remark AS remark, o.created_at AS createdAt, o.updated_at AS updatedAt, COALESCE(t.paid_amount, 0) AS paidAmount FROM orders o JOIN customers c ON o.customer_id = c.id LEFT JOIN () t ON o.id = t.order_id
AND o.status = #{q.status}
AND o.customer_id = #{q.customerId}
AND o.order_no LIKE #{q.orderNo}
AND o.customer_order_no LIKE #{q.customerOrderNo}
AND o.order_date >= #{q.dateFrom}
AND o.order_date <= #{q.dateTo}
ORDER BY o.id DESC

SELECT o.id, o.order_no AS orderNo, o.customer_order_no AS customerOrderNo, o.customer_id AS customerId, o.order_date AS orderDate, o.total_amount AS totalAmount, o.status AS status, o.expected_delivery AS expectedDelivery, o.due_date AS dueDate, o.remark AS remark, s.shipment_date AS shipmentDate, s.tracking_no AS trackingNo FROM orders o JOIN shipments s ON o.id = s.order_id
AND o.customer_id = #{customerId} AND o.status IN ('shipped', 'paid') AND s.confirmed = 1
AND s.shipment_date >= #{from}
AND s.shipment_date <= #{to}
ORDER BY s.shipment_date ASC, o.id ASC

